-- Deutschlify · telc AI Writing Examiner · seed: official source register and rubric versions
-- Generated from examiner/source-register.json and examiner/rubrics/*.json. Idempotent.







-- Point each profile at its rubric. Profiles stay inactive until the examiner pipeline is released.
update public.exam_profiles p set current_rubric_version_id = v.id from public.rubric_versions v where v.exam_profile_id = p.id and v.version = '2026-11-13.1' and p.current_rubric_version_id is null;
